[ExtensionOf(classStr(PriceDisc))]
public final class GUPPriceDisc_Extension
{
    private SalesPurchLineInterface salesPurchLineInterface;
    private RefRecId itemBasePriceRecId;

}

Method.Source:
public boolean findItemPrice()
{
    boolean ret = next findItemPrice();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && 
        this.parmPriceDiscParameters().parmModuleType() == ModuleInventPurchSales::Purch &&
        salesPurchLineInterface.inventTable().inventTableModulePurch().BasePricePurchase)
    {
        ret = this.findBasePricePurchase() || ret;
    }

    return ret;
}

public RefRecId parmItemBasePriceRecId(RefRecId _itemBasePriceRecId = itemBasePriceRecId)
{
    itemBasePriceRecId = _itemBasePriceRecId;

    return itemBasePriceRecId;
}

private boolean findBasePricePurchase()
{
    date poCreatedDateTime = DatetimeUtil::Date(salesPurchLineInterface.salesPurchTable().CreatedDateTime);
    GUPItemBasePrice itemBasePrice = GUPItemBasePrice::findCurrent(
        salesPurchLineInterface.parmItemId(),
        GUPBasePriceType::BasePricePurchase,
        salesPurchLineInterface.parmInventDimId(),
        poCreatedDateTime,
        salesPurchLineInterface.parmOrderAccount());

    if (itemBasePrice)
    {
        price = this.convert(itemBasePrice);
        priceUnit = 1;
        this.parmItemBasePriceRecId(itemBasePrice.RecId);
        return true;
    }

    return false;
}

private Price convert(GUPItemBasePrice itemBasePrice)
{
    PriceConvertFactory priceConvertFactory = PriceConvertFactory::newItemPrice(
        itemBasePrice.ItemId,
        itemBasePrice.Unitid,
        itemBasePrice.Price,
        1,
        itemBasePrice.Markup,
        itemBasePrice.PriceQty,
        Ledger::accountingCurrency(CompanyInfo::current()));

    priceConvertFactory.parmNewCurrencyCode(salesPurchLineInterface.parmCurrencyCode());
    priceConvertFactory.parmNewUnitId(salesPurchLineInterface.parmUnitId());
    PriceConvert priceConvert = priceConvertFactory.priceConvert();

    return priceConvert.parmPrice();
}
